"""Execute prepared inputs only after an independently fetched checkout is frozen."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import time

HERE = Path(__file__).resolve().parent


def sha(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def git(root, *args):
    return subprocess.check_output(['git', '--no-optional-locks', '-c', 'core.hooksPath=/dev/null',
                                    '-C', str(root), *args], text=True).strip()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--checkout', type=Path, required=True)
    parser.add_argument('--expected-commit', required=True)
    parser.add_argument('--out', type=Path, required=True)
    parser.add_argument('--timeout', type=int, default=1800)
    args = parser.parse_args()
    if not re.fullmatch('[0-9a-f]{40}', args.expected_commit):
        parser.error('expected-commit must be the complete independently fetched published commit')
    root = args.checkout.resolve(strict=True)
    if git(root, 'rev-parse', 'HEAD') != args.expected_commit:
        raise ValueError('published checkout is not at the expected commit')
    if git(root, 'status', '--porcelain', '--untracked-files=all', '--ignore-submodules=none'):
        raise ValueError('published checkout must be clean before execution')
    preflight = json.loads((HERE/'preflight.json').read_text())
    if preflight['missing'] or preflight['pin_mismatches']:
        raise ValueError('prepared input paths or pins are incomplete')
    for name, field in [('command.json', 'command_sha256'), ('env.json', 'environment_sha256'),
                        ('queries.txt', 'queries_sha256'), ('kits.json', 'kits_sha256'),
                        ('source-dependencies.json', 'source_dependencies_sha256')]:
        if sha(HERE/name) != preflight[field]:
            raise ValueError('prepared input changed; rerun preparation: '+name)
    for path, field in [('superhunter/product_supply/component-control-contracts.json', 'component_contract_sha256'),
                        ('superhunter/product_supply/native-capability-contracts.json', 'native_contract_sha256')]:
        if sha(root/path) != preflight[field]:
            raise ValueError('published acceptance contract differs from preparation: '+path)
    dependencies = json.loads((HERE/'source-dependencies.json').read_text())
    for domain, files in dependencies.items():
        for path, proof in files.items():
            if sha(root/path) != proof['current_sha256']:
                raise ValueError('re-evaluate the changed component before replay: '+domain+':'+path)
    argv = json.loads((HERE/'command.json').read_text())
    source = Path(argv[argv.index('--source-references')+1]).resolve(strict=True)
    if git(root, 'rev-parse', 'HEAD:upstream') != preflight['source_tree']:
        raise ValueError('published source catalog tree differs from preparation')
    if git(source, 'rev-parse', 'HEAD:upstream') != preflight['source_tree']:
        raise ValueError('materialized source catalog tree differs from preparation')
    for row in preflight['argv_paths'] + preflight['native_kits']:
        if not Path(row['path']).exists():
            raise ValueError('prepared path is no longer available: '+row['path'])
    for row in preflight['file_checks']:
        if not row['exists'] or sha(row['path']) != row['sha256']:
            raise ValueError('prepared artifact changed: '+row['label'])
    # Runtime paths and credentials are not copied from the caller's environment.
    env = json.loads((HERE/'env.json').read_text())
    out = args.out.resolve()
    if out.is_relative_to(root) or out.is_relative_to(source):
        raise ValueError('replay output must stay outside source checkouts')
    out.mkdir(parents=True, exist_ok=False)
    for name in ('tmp', 'home'):
        (out/name).mkdir()
    env.update(TMPDIR=str(out/'tmp'), HOME=str(out/'home'))
    (out/'command.json').write_text(json.dumps({'argv': argv, 'cwd': str(root),
        'commit': args.expected_commit, 'tree': git(root, 'rev-parse', 'HEAD^{tree}'),
        'stdin': str(HERE/'queries.txt')}, indent=2)+'\n')
    (out/'env.json').write_text(json.dumps(env, sort_keys=True, indent=2)+'\n')
    start = time.monotonic()
    failure = None
    returncode = None
    with (HERE/'queries.txt').open('rb') as queries, (out/'session.jsonl').open('xb') as stdout, \
            (out/'stderr.txt').open('xb') as stderr:
        try:
            returncode = subprocess.run(argv, cwd=root, env=env, stdin=queries,
                                        stdout=stdout, stderr=stderr, timeout=args.timeout).returncode
        except subprocess.TimeoutExpired:
            failure = 'outer replay deadline exceeded'
    data = (out/'session.jsonl').read_bytes()
    clean = not git(root, 'status', '--porcelain', '--untracked-files=all', '--ignore-submodules=none')
    result = {'commit': args.expected_commit, 'returncode': returncode, 'failure': failure,
              'seconds': round(time.monotonic()-start, 2), 'lines': len(data.splitlines()),
              'bytes': len(data), 'transcript_sha256': hashlib.sha256(data).hexdigest(),
              'clean_checkout_after': clean, 'independent_verifier_run': False,
              'success_requires_independent_consolidated_verifier': True}
    (out/'execution.json').write_text(json.dumps(result, sort_keys=True, indent=2)+'\n')
    print(json.dumps(result), flush=True)
    return int(returncode != 0 or failure is not None or not clean or result['lines'] != 222)


if __name__ == '__main__':
    raise SystemExit(main())
